 torch.set_num_threads(4);decision=read(RUN/'deployment_decision.json');assert decision['eligible'] and decision['test_evaluated'] and not decision['installed'];assert decision['protected_artifacts_unchanged'];assert all(digest(ROOT/name)==sha for name,sha in read(RUN/'protected_artifacts.json').items())
