 p=ROOT/'frontend/src/research/TrainingEvidence.jsx';s=p.read_text(encoding='utf-8');s=s.replace("c?.training_stage?.startsWith('full_network_pure_')&&","c?.training_stage?.startsWith('full_network_pure_')&&c.training_stage!=='full_network_pure_coverage_repair'&&")
