 s=s.replace("['spatial_generalization','pure_fusdense']","['spatial_generalization','pure_fusdense','pure_orientation_repair']");s=s.replace("data.latest_experiment.method==='pure_fusdense'?'pure_experiment':'experiment'","data.latest_experiment.method==='pure_orientation_repair'?'repair':data.latest_experiment.method==='pure_fusdense'?'pure_experiment':'experiment'");s=s.replace('All new spatial refinement validation epochs, including rejected results','All new validation epochs, including rejected results');p.write_text(s,encoding='utf-8')
 p=ROOT/'backend/main.py';s=p.read_text(encoding='utf-8');anchor="allowed={'confusion':";assert anchor in s;s=s.replace(anchor,"allowed={'repair':'pure_orientation_validation.png','repair_errors':'pure_orientation_validation_confusion.png','confusion':",1);p.write_text(s,encoding='utf-8')
