 decision.update(installed=True,source_tests_passed=n,source_test_seconds=seconds);write_json(RUN/'deployment_decision.json',decision);write_json(RUN/'app_integration_receipt.json',{'installed':True,'checkpoint_sha256':decision['checkpoint_sha256'],'tests':n,'test_seconds':seconds,'frontend_build':'pass','ppt_pending':True,'github_published':False});print(json.dumps({'installed':True,'tests':n,'seconds':seconds,'checkpoint':decision['checkpoint_sha256']},indent=2))
